#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# APICenter deploy setup wizard (#149).
#
# Walks an operator through the manual setup this round's changes need before the next deploy:
# service accounts, Secret Manager secrets, IAM grants, provider webhooks, GitHub secrets, Google
# sign-in, the history purge job, the database baseline, and the deploy order.
#
#   bash scripts/setup/deploy-setup-wizard.sh
#
# It checks before it creates anything, asks before every create, grant, or provider change, and
# never prints a secret value. Secrets go only to Secret Manager or GitHub. Non-secret answers, such
# as the Supabase project ref, go to .env.deploy-wizard (gitignored) unless ENV_FILE is set in the
# environment. Running it again is safe.

TOTAL_STAGES=13

# Never trace: a traced command would show secret values.
set +x

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"
# The library defaults ENV_FILE to .env. Keep this wizard's answers in their own file unless ENV_FILE was given.
if ! printenv ENV_FILE >/dev/null 2>&1; then ENV_FILE=".env.deploy-wizard"; fi

PROJECT_ID="apicenter-alpha-20260623"
REGION="asia-southeast1"
GATEWAY_URL="https://api-center.itsandbox.site"
ACCOUNT_DOMAIN="${PROJECT_ID}.iam.gserviceaccount.com"
GAUTH_SA="apicenter-gauth-runtime@${ACCOUNT_DOMAIN}"
GATEWAY_SA="api-center-cloud-run@${ACCOUNT_DOMAIN}"
SHARED_SA="apicenter-shared-services-runtime@${ACCOUNT_DOMAIN}"
PURGE_SA="apicenter-history-purge@${ACCOUNT_DOMAIN}"
DEPLOYER_SA="apicenter-cloudbuild-deployer@${ACCOUNT_DOMAIN}"
IMAGE_REPOSITORY="${REGION}-docker.pkg.dev/${PROJECT_ID}/api-center"
SECRET_ACCESSOR="roles/secretmanager.secretAccessor"
# Events the payment runtime handles. payment.paid includes payment-link payments (origin "links").
PAYMONGO_EVENTS="checkout_session.payment.paid,payment.paid,link.payment.paid"
# Resend events the gateway maps to delivery statuses (delivery-webhook.controller.ts).
RESEND_EVENTS="email.sent, email.delivered, email.delivery_delayed, email.bounced, email.complained, email.failed, email.suppressed, email.opened, email.clicked"

PROJECT_NUMBER=""
PAYMONGO_KEY=""
WIZARD_SECRET_INPUT=""

# ── Helpers ───────────────────────────────────────────────────────────────

ok()    { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die()   { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET" >&2; exit 1; }
# later records a step the operator still has to do. finish lists them all.
later() { SKIPPED+=("$1"); warn "left for later: $1"; }

account_exists() { gcloud iam service-accounts describe "$1" --project="$PROJECT_ID" >/dev/null 2>&1; }
secret_exists()  { gcloud secrets describe "$1" --project="$PROJECT_ID" >/dev/null 2>&1; }

# policy_has_binding ROLE MEMBER [EXPRESSION] reads an IAM policy as JSON on stdin. It succeeds when MEMBER
# holds ROLE with exactly that condition expression, or with no condition when EXPRESSION is omitted.
policy_has_binding() {
  python3 -c '
import json, sys
role, member = sys.argv[1], sys.argv[2]
expression = sys.argv[3] if len(sys.argv) > 3 else None
policy = json.loads(sys.stdin.read() or "{}")
for binding in policy.get("bindings", []):
    condition = (binding.get("condition") or {}).get("expression")
    if binding.get("role") == role and member in binding.get("members", []) and condition == expression:
        sys.exit(0)
sys.exit(1)
' "$@"
}

# project_has_binding ROLE MEMBER [EXPRESSION] checks the IAM policy of PROJECT_ID.
project_has_binding() {
  gcloud projects get-iam-policy "$PROJECT_ID" --format=json 2>/dev/null | policy_has_binding "$@"
}

# ensure_service_account NAME "Display name" creates NAME@PROJECT_ID when it is missing.
ensure_service_account() {
  local name="$1" display="$2" email="$1@${ACCOUNT_DOMAIN}"
  if account_exists "$email"; then
    ok "$email exists"
  elif ! confirm "Create the service account $email?"; then
    later "create the service account $email"
  elif gcloud iam service-accounts create "$name" --project="$PROJECT_ID" --display-name="$display" --quiet; then
    ok "created $email"
  else
    later "create the service account $email (gcloud failed; see the error above)"
  fi
}

# ensure_random_secret NAME creates NAME from 48 random bytes when it is missing. Nobody sees the value.
# tr drops the newline openssl prints, which Cloud Run would otherwise pass into the environment variable.
ensure_random_secret() {
  local secret="$1"
  if secret_exists "$secret"; then
    ok "$secret exists"
  elif ! confirm "Create $secret with a random value?"; then
    later "create the secret $secret"
  elif openssl rand -base64 48 | tr -d '\n' | gcloud secrets create "$secret" --project="$PROJECT_ID" \
      --data-file=- --replication-policy=automatic --quiet; then
    ok "created $secret"
  else
    later "create the secret $secret (gcloud failed; see the error above)"
  fi
}

# ensure_pasted_secret NAME "Prompt" [replace] stores a value entered with hidden input. It creates NAME when it
# is missing. An existing NAME is kept, unless the third argument is "replace" and the operator wants a new version.
ensure_pasted_secret() {
  local secret="$1" prompt="$2" mode="${3:-keep}" exists=false question
  if secret_exists "$secret"; then exists=true; fi
  if $exists && [[ "$mode" != "replace" ]]; then
    ok "$secret exists"
    return 0
  fi
  question="Create $secret from a value you paste?"
  if $exists; then question="Add a new version of $secret from a value you paste?"; fi
  if ! confirm "$question"; then
    if $exists; then ok "kept the current $secret"; else later "create the secret $secret"; fi
    return 0
  fi
  WIZARD_SECRET_INPUT=""
  ask_secret WIZARD_SECRET_INPUT "$prompt"
  if [[ -z "$WIZARD_SECRET_INPUT" ]]; then
    later "store a value in $secret (nothing was entered)"
  elif $exists; then
    if printf '%s' "$WIZARD_SECRET_INPUT" | gcloud secrets versions add "$secret" --project="$PROJECT_ID" \
        --data-file=- --quiet; then
      ok "added a new version of $secret"
    else
      later "add a new version of $secret (gcloud failed; see the error above)"
    fi
  elif printf '%s' "$WIZARD_SECRET_INPUT" | gcloud secrets create "$secret" --project="$PROJECT_ID" \
      --data-file=- --replication-policy=automatic --quiet; then
    ok "created $secret"
  else
    later "create the secret $secret (gcloud failed; see the error above)"
  fi
  WIZARD_SECRET_INPUT=""
}

# grant_secret_accessor SECRET ACCOUNT gives ACCOUNT roles/secretmanager.secretAccessor on SECRET.
grant_secret_accessor() {
  local secret="$1" account="$2" member="serviceAccount:$2"
  if ! secret_exists "$secret"; then
    later "give $account read access to $secret, which does not exist yet"
  elif ! account_exists "$account"; then
    later "give $account read access to $secret once that service account exists"
  elif gcloud secrets get-iam-policy "$secret" --project="$PROJECT_ID" --format=json 2>/dev/null \
      | policy_has_binding "$SECRET_ACCESSOR" "$member"; then
    ok "$account can read $secret"
  elif ! confirm "Give $account read access to $secret?"; then
    later "give $account $SECRET_ACCESSOR on $secret"
  elif gcloud secrets add-iam-policy-binding "$secret" --project="$PROJECT_ID" \
      --member="$member" --role="$SECRET_ACCESSOR" >/dev/null; then
    ok "$account can now read $secret"
  else
    later "give $account $SECRET_ACCESSOR on $secret (gcloud failed; see the error above)"
  fi
}

# ensure_project_binding ROLE ACCOUNT [EXPRESSION TITLE DESCRIPTION] binds ROLE to ACCOUNT on PROJECT_ID, with an
# IAM condition when EXPRESSION is given.
ensure_project_binding() {
  local role="$1" account="$2" expression="${3:-}" title="${4:-}" description="${5:-}"
  local member="serviceAccount:$2" condition="None" where=""
  local -a check=("$role" "$member")
  if [[ -n "$expression" ]]; then
    condition="expression=${expression},title=${title},description=${description}"
    check+=("$expression")
    where=" with the condition $expression"
  fi
  if ! account_exists "$account"; then
    later "bind $role to $account once that service account exists"
  elif project_has_binding "${check[@]}"; then
    ok "$account holds $role$where"
  elif ! confirm "Bind $role to $account on $PROJECT_ID$where?"; then
    later "bind $role to $account on $PROJECT_ID$where"
  elif gcloud projects add-iam-policy-binding "$PROJECT_ID" --member="$member" --role="$role" \
      --condition="$condition" --quiet >/dev/null; then
    ok "bound $role to $account"
  else
    later "bind $role to $account on $PROJECT_ID (gcloud failed; see the error above)"
  fi
}

# ensure_custom_role ID TITLE DESCRIPTION PERMISSIONS makes sure the custom role ID exists in PROJECT_ID with
# exactly PERMISSIONS, a comma-separated list.
ensure_custom_role() {
  local id="$1" title="$2" description="$3" permissions="$4" described state
  if ! described=$(gcloud iam roles describe "$id" --project="$PROJECT_ID" --format=json 2>/dev/null); then
    if ! confirm "Create the custom role $id with $permissions?"; then
      later "create the custom role $id in $PROJECT_ID with $permissions"
    elif gcloud iam roles create "$id" --project="$PROJECT_ID" --title="$title" --description="$description" \
        --permissions="$permissions" --stage=GA --quiet >/dev/null; then
      ok "created the custom role $id"
    else
      later "create the custom role $id (gcloud failed; see the error above)"
    fi
    return 0
  fi
  state=$(python3 -c '
import json, sys
role = json.loads(sys.stdin.read())
if role.get("deleted"):
    print("deleted")
elif sorted(role.get("includedPermissions", [])) == sorted(sys.argv[1].split(",")):
    print("current")
else:
    print("different")
' "$permissions" <<<"$described") || state="different"
  if [[ "$state" == "current" ]]; then
    ok "the custom role $id has the expected permissions"
  elif [[ "$state" == "deleted" ]] && confirm "The custom role $id was deleted. Restore it with $permissions?"; then
    if gcloud iam roles undelete "$id" --project="$PROJECT_ID" --quiet >/dev/null \
        && gcloud iam roles update "$id" --project="$PROJECT_ID" --permissions="$permissions" --quiet >/dev/null; then
      ok "restored the custom role $id"
    else
      later "restore the custom role $id (gcloud failed; see the error above)"
    fi
  elif [[ "$state" == "different" ]] && confirm "The custom role $id has other permissions. Set them to $permissions?"; then
    if gcloud iam roles update "$id" --project="$PROJECT_ID" --permissions="$permissions" --quiet >/dev/null; then
      ok "updated the custom role $id"
    else
      later "update the custom role $id (gcloud failed; see the error above)"
    fi
  else
    later "make the custom role $id in $PROJECT_ID grant exactly $permissions"
  fi
}

# ensure_deployer_can_act_as ACCOUNT makes sure the Cloud Build deployer may deploy services that run as ACCOUNT.
ensure_deployer_can_act_as() {
  local account="$1" member="serviceAccount:$DEPLOYER_SA" role
  if ! account_exists "$DEPLOYER_SA"; then
    later "check that $DEPLOYER_SA can act as $account (that service account was not found)"
    return 0
  fi
  if ! account_exists "$account"; then
    later "give $DEPLOYER_SA roles/iam.serviceAccountUser on $account once it exists"
    return 0
  fi
  for role in roles/iam.serviceAccountUser roles/editor roles/owner; do
    if project_has_binding "$role" "$member"; then
      ok "$DEPLOYER_SA holds $role on $PROJECT_ID, so it can act as $account"
      return 0
    fi
  done
  if gcloud iam service-accounts get-iam-policy "$account" --project="$PROJECT_ID" --format=json 2>/dev/null \
      | policy_has_binding roles/iam.serviceAccountUser "$member"; then
    ok "$DEPLOYER_SA can act as $account"
  elif ! confirm "Give $DEPLOYER_SA roles/iam.serviceAccountUser on $account?"; then
    later "give $DEPLOYER_SA roles/iam.serviceAccountUser on $account before Cloud Build deploys gauth"
  elif gcloud iam service-accounts add-iam-policy-binding "$account" --project="$PROJECT_ID" \
      --member="$member" --role=roles/iam.serviceAccountUser >/dev/null; then
    ok "$DEPLOYER_SA can now act as $account"
  else
    later "give $DEPLOYER_SA roles/iam.serviceAccountUser on $account (gcloud failed; see the error above)"
  fi
}

# paymongo ACTION ARGS... calls PayMongo's webhook API with the secret key in PAYMONGO_KEY, passed through the
# environment so it never appears on a command line. Every webhook response includes the webhook's secret_key,
# so raw JSON is never printed: only IDs, URLs, statuses and events.
#   list URL EVENTS           lists webhooks, then prints RESULT|match|ID|STATUS|MISSING or RESULT|none
#   add-events ID URL EVENTS  adds EVENTS with PUT /v1/webhooks/ID, then prints RESULT|same-secret or RESULT|new-secret
#   enable ID                 re-enables a disabled webhook with POST /v1/webhooks/ID/enable
#   signing-secret ID         writes the webhook's secret_key into a pipe, and refuses a terminal
paymongo() {
  PAYMONGO_SECRET_KEY="$PAYMONGO_KEY" python3 - "$@" <<'PY'
import base64, json, os, sys, urllib.error, urllib.request

API = "https://api.paymongo.com/v1/webhooks"
TOKEN = base64.b64encode((os.environ["PAYMONGO_SECRET_KEY"] + ":").encode()).decode()


def call(method, url, payload=None):
    data = None if payload is None else json.dumps(payload).encode()
    request = urllib.request.Request(url, data=data, method=method, headers={
        "Authorization": "Basic " + TOKEN, "Accept": "application/json",
        "Content-Type": "application/json", "User-Agent": "apicenter-deploy-setup-wizard"})
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        try:
            detail = json.load(error)["errors"][0]["detail"]
        except Exception:
            detail = error.reason
        sys.exit("PayMongo returned HTTP %s: %s" % (error.code, detail))
    except urllib.error.URLError as error:
        sys.exit("Could not reach PayMongo: %s" % error.reason)


def show(hook):
    attributes = hook.get("attributes") or {}
    print("  %s  %s  %s" % (hook.get("id"), attributes.get("status"), attributes.get("url")))
    print("      events: %s" % (", ".join(attributes.get("events") or []) or "(none)"))


action, args = sys.argv[1], sys.argv[2:]
if action == "list":
    url, required = args[0], args[1].split(",")
    body = call("GET", API)
    hooks = body.get("data") or []
    match = None
    for hook in hooks:
        show(hook)
        if (hook.get("attributes") or {}).get("url") == url:
            match = hook
    if not hooks:
        print("  (no webhooks)")
    if body.get("has_more"):
        print("  PayMongo has more webhooks than it returned.")
    if match:
        attributes = match.get("attributes") or {}
        missing = [event for event in required if event not in (attributes.get("events") or [])]
        print("|".join(["RESULT", "match", match.get("id") or "", attributes.get("status") or "", ",".join(missing)]))
    else:
        print("RESULT|none")
elif action == "add-events":
    hook_id, url, wanted = args[0], args[1], args[2].split(",")
    before = call("GET", "%s/%s" % (API, hook_id))["data"]["attributes"]
    events = list(before.get("events") or [])
    events += [event for event in wanted if event not in events]
    after = call("PUT", "%s/%s" % (API, hook_id), {"data": {"attributes": {"url": url, "events": events}}})["data"]
    show(after)
    unchanged = (after.get("attributes") or {}).get("secret_key") == before.get("secret_key")
    print("RESULT|same-secret" if unchanged else "RESULT|new-secret")
elif action == "enable":
    show(call("POST", "%s/%s/enable" % (API, args[0]))["data"])
elif action == "signing-secret":
    if sys.stdout.isatty():
        sys.exit("Refusing to write a signing secret to a terminal.")
    sys.stdout.write(call("GET", "%s/%s" % (API, args[0]))["data"]["attributes"]["secret_key"])
PY
}

# paymongo_store_new_secret ENV ID SECRET stores a webhook's new signing secret without showing it.
paymongo_store_new_secret() {
  local environment="$1" hook_id="$2" signing_secret="$3"
  warn "PayMongo returned a different signing secret for $hook_id."
  if confirm "Store it as a new version of $signing_secret? It is not shown."; then
    if paymongo signing-secret "$hook_id" \
        | gcloud secrets versions add "$signing_secret" --project="$PROJECT_ID" --data-file=- --quiet; then
      ok "stored it. Redeploy apicenter-payments-$environment to use it."
      return 0
    fi
  fi
  later "store the new signing secret of $hook_id in $signing_secret, then redeploy apicenter-payments-$environment"
}

# paymongo_environment ENV checks the PayMongo webhook of one environment, test or live.
paymongo_environment() {
  local environment="$1" url="$GATEWAY_URL/api/v1/shared/payment/webhooks/$1"
  local key_secret="apicenter-payments-$1-secret-key" signing_secret="apicenter-payments-$1-webhook-secret"
  local listing updated kind hook_id hook_status missing
  printf '\n'
  say "${BOLD}PayMongo $environment${RESET}: $url"
  if ! secret_exists "$key_secret"; then
    later "check the PayMongo $environment webhook ($key_secret does not exist)"
    return 0
  fi
  # The key goes into a shell variable only. It reaches python through the environment and is never printed.
  if ! PAYMONGO_KEY=$(gcloud secrets versions access latest --secret="$key_secret" --project="$PROJECT_ID" 2>/dev/null) \
      || [[ -z "$PAYMONGO_KEY" ]]; then
    PAYMONGO_KEY=""
    later "check the PayMongo $environment webhook (could not read $key_secret)"
    return 0
  fi
  if ! listing=$(paymongo list "$url" "$PAYMONGO_EVENTS"); then
    PAYMONGO_KEY=""
    later "check the PayMongo $environment webhook (the PayMongo API call failed)"
    return 0
  fi
  printf '%s\n' "${listing%$'\n'*}"
  IFS='|' read -r _ kind hook_id hook_status missing <<<"${listing##*$'\n'}"
  if [[ "$kind" != "match" ]]; then
    warn "No PayMongo $environment webhook points at $url."
    say "If a webhook listed above is meant for this runtime, change its URL with PUT /v1/webhooks/<id>"
    say "(https://docs.paymongo.com/reference/update-a-webhook). Otherwise create one with POST /v1/webhooks"
    say "(https://docs.paymongo.com/reference/create-a-webhook): url $url,"
    say "events ${PAYMONGO_EVENTS//,/, }."
    say "$signing_secret must hold that webhook's signing secret (secret_key). A new webhook has a new one;"
    say "after storing it as a new version, redeploy apicenter-payments-$environment."
    later "point a PayMongo $environment webhook at $url and keep $signing_secret in step with it"
  else
    if [[ "$hook_status" != "enabled" ]]; then
      warn "$hook_id is $hook_status, so PayMongo does not deliver its events."
      if ! confirm "Re-enable $hook_id with POST /v1/webhooks/$hook_id/enable?"; then
        later "re-enable the PayMongo $environment webhook $hook_id"
      elif ! paymongo enable "$hook_id"; then
        later "re-enable the PayMongo $environment webhook $hook_id (the PayMongo API call failed)"
      fi
    fi
    if [[ -z "$missing" ]]; then
      ok "$hook_id receives every event the runtime handles"
    elif ! confirm "$hook_id is missing ${missing//,/, }. Add them with PUT /v1/webhooks/$hook_id?"; then
      later "add ${missing//,/, } to the PayMongo $environment webhook $hook_id (PUT /v1/webhooks/$hook_id)"
    elif ! updated=$(paymongo add-events "$hook_id" "$url" "$missing"); then
      later "add ${missing//,/, } to the PayMongo $environment webhook $hook_id (the PayMongo API call failed)"
    else
      printf '%s\n' "${updated%$'\n'*}"
      if [[ "${updated##*$'\n'}" == "RESULT|same-secret" ]]; then
        ok "added the events; the signing secret did not change"
      else
        paymongo_store_new_secret "$environment" "$hook_id" "$signing_secret"
      fi
    fi
  fi
  if ! secret_exists "$signing_secret"; then
    later "store the PayMongo $environment signing secret in $signing_secret"
  fi
  PAYMONGO_KEY=""
}

# ── Stages ────────────────────────────────────────────────────────────────

stage_tools() {
  local account current missing=() tool
  stage "Tools and Google Cloud access"
  say "This wizard prepares $PROJECT_ID for the next deploy. It checks before it creates anything, asks"
  say "before every change, and never shows a secret value."
  if ! command -v gcloud >/dev/null 2>&1; then
    warn "The Google Cloud CLI (gcloud) is not installed."
    open_url "https://cloud.google.com/sdk/docs/install"
    step "Install it for this system. If the installer changes your PATH, open a new terminal and run the wizard again."
    pause "Press Enter after gcloud is installed"
    hash -r
    if ! command -v gcloud >/dev/null 2>&1; then
      die "gcloud is still not installed. Install the Google Cloud CLI, then run this wizard again."
    fi
  fi
  ok "gcloud is installed"

  account=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
  if [[ -z "$account" ]]; then
    warn "No Google account is signed in to gcloud."
    if confirm "Run gcloud auth login now? It opens a browser."; then
      gcloud auth login || true
    fi
    account=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
    if [[ -z "$account" ]]; then
      die "gcloud has no active account. Run gcloud auth login, then run this wizard again."
    fi
  fi
  ok "gcloud is signed in as $account"

  PROJECT_NUMBER=$(gcloud projects describe "$PROJECT_ID" --format='value(projectNumber)' 2>/dev/null || true)
  if [[ -z "$PROJECT_NUMBER" ]]; then
    die "$account cannot open project $PROJECT_ID. Sign in with an account that can, then run this wizard again."
  fi
  current=$(gcloud config get-value project 2>/dev/null || true)
  if [[ "$current" == "$PROJECT_ID" ]]; then
    ok "gcloud's default project is $PROJECT_ID"
  elif confirm "Set gcloud's default project to $PROJECT_ID? It is now ${current:-unset}."; then
    if gcloud config set project "$PROJECT_ID" --quiet >/dev/null 2>&1; then
      ok "gcloud's default project is now $PROJECT_ID"
    else
      warn "could not change the default project; this wizard still names $PROJECT_ID in every command"
    fi
  else
    note "Your default project stays as it is. This wizard names $PROJECT_ID in every command."
  fi
  # Commands that take no --project flag use this project too.
  export CLOUDSDK_CORE_PROJECT="$PROJECT_ID"

  for tool in openssl python3; do
    command -v "$tool" >/dev/null 2>&1 || missing+=("$tool")
  done
  if (( ${#missing[@]} )); then
    die "This wizard needs ${missing[*]}. Install it (for example: sudo apt-get install ${missing[*]}), then run the wizard again."
  fi
  ok "openssl and python3 are installed"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    ok "gh is signed in (only stage 9 needs it)"
  else
    note "gh is missing or signed out. Only stage 9, the GitHub secrets, needs it."
  fi
  pause
}

stage_gauth_account() {
  stage "gauth runtime service account"
  say "gauth runs as its own identity (#140), set in infra/gcp/cloud-run/gauth.yaml:"
  say "$GAUTH_SA"
  ensure_service_account apicenter-gauth-runtime "APICenter gauth runtime"
  printf '\n'
  say "Cloud Build deploys gauth as that account, so the deployer must be allowed to act as it."
  ensure_deployer_can_act_as "$GAUTH_SA"
  pause
}

stage_gauth_secrets() {
  local secret
  stage "gauth configuration secrets"
  say "gauth.yaml reads six secrets. The runbook used to grant gauth only the three apicenter-gauth-*"
  say "ones, so a revision deployed by following it could not start."
  ensure_random_secret apicenter-gauth-admin-token
  ensure_random_secret apicenter-gauth-google-oauth-state-secret
  if ! secret_exists apicenter-gauth-database-url-live; then
    say "apicenter-gauth-database-url-live is the Postgres URL gauth connects with. Its user must be a login"
    say "role that is a member of gauth_runtime, the role that holds the shared_gauth grants."
  fi
  ensure_pasted_secret apicenter-gauth-database-url-live "Paste the gauth database URL (hidden):"
  printf '\n'
  for secret in apicenter-gauth-admin-token apicenter-gauth-google-oauth-state-secret \
      apicenter-gauth-database-url-live apicenter-shared-google-client-id-prod \
      apicenter-shared-google-client-secret-prod apicenter-shared-google-redirect-uri-prod; do
    grant_secret_accessor "$secret" "$GAUTH_SA"
  done
  printf '\n'
  say "The gateway sends the same admin token on its admin calls to gauth."
  grant_secret_accessor apicenter-gauth-admin-token "$GATEWAY_SA"
  pause
}

stage_gauth_client_secrets() {
  local creator="projects/$PROJECT_ID/roles/apicenterGauthSecretCreator"
  local client="projects/$PROJECT_ID/roles/apicenterGauthClientSecrets"
  local expression
  stage "Per-project Google client secrets"
  say "A project that uses its own Google client keeps it in a secret named apic-gauth-<projectId>-<environment>"
  say "in $PROJECT_ID, which gauth.yaml sets as GAUTH_SECRETS_PROJECT_ID. Instead of roles/secretmanager.admin,"
  say "which would open every secret in the project, gauth gets two custom roles:"
  step "apicenterGauthSecretCreator: secretmanager.secrets.create, bound on the project with no condition."
  say "  Secret Manager checks secret creation on the project, so a name condition cannot limit it."
  step "apicenterGauthClientSecrets: get, delete, add versions to, and read secrets whose name starts with apic-gauth-."
  warn "gauth can create secrets with any name, but can only read, update, or delete apic-gauth-* secrets."
  printf '\n'
  ensure_custom_role apicenterGauthSecretCreator "APICenter gauth secret creator" \
    "Create Secret Manager secrets for per-project gauth Google clients" \
    secretmanager.secrets.create
  ensure_custom_role apicenterGauthClientSecrets "APICenter gauth client secrets" \
    "Read, update, and delete secrets named apic-gauth-*" \
    secretmanager.secrets.get,secretmanager.secrets.delete,secretmanager.versions.add,secretmanager.versions.access,secretmanager.versions.get
  PROJECT_NUMBER=$(gcloud projects describe "$PROJECT_ID" --format='value(projectNumber)' 2>/dev/null || true)
  if [[ -z "$PROJECT_NUMBER" ]]; then
    later "bind apicenterGauthClientSecrets to $GAUTH_SA (could not look up the project number)"
    pause
    return 0
  fi
  expression="resource.name.startsWith(\"projects/${PROJECT_NUMBER}/secrets/apic-gauth-\")"
  ensure_project_binding "$creator" "$GAUTH_SA"
  ensure_project_binding "$client" "$GAUTH_SA" "$expression" gauth-client-secrets "Only secrets named apic-gauth-*"
  if project_has_binding roles/secretmanager.admin "serviceAccount:$GAUTH_SA"; then
    warn "gauth also holds roles/secretmanager.admin on $PROJECT_ID, which opens every secret there."
    if ! project_has_binding "$creator" "serviceAccount:$GAUTH_SA" \
        || ! project_has_binding "$client" "serviceAccount:$GAUTH_SA" "$expression"; then
      later "remove roles/secretmanager.admin from $GAUTH_SA on $PROJECT_ID once both custom roles are bound"
    elif ! confirm "Remove roles/secretmanager.admin from $GAUTH_SA now that both custom roles are bound?"; then
      later "remove roles/secretmanager.admin from $GAUTH_SA on $PROJECT_ID"
    elif gcloud projects remove-iam-policy-binding "$PROJECT_ID" --member="serviceAccount:$GAUTH_SA" \
        --role=roles/secretmanager.admin --condition=None --quiet >/dev/null; then
      ok "removed roles/secretmanager.admin from $GAUTH_SA"
    else
      later "remove roles/secretmanager.admin from $GAUTH_SA on $PROJECT_ID (gcloud failed; see the error above)"
    fi
  fi
  pause
}

stage_email_admin_token() {
  stage "Email admin token"
  say "apicenter-email-admin-token (#139) is new. The email runtime (email.yaml) and the gateway"
  say "(api-center.prod.yaml) both read it."
  ensure_random_secret apicenter-email-admin-token
  grant_secret_accessor apicenter-email-admin-token "$SHARED_SA"
  grant_secret_accessor apicenter-email-admin-token "$GATEWAY_SA"
  pause
}

stage_resend_webhook() {
  local secret="apicenter-shared-resend-webhook-secret-prod" mode="keep"
  stage "Resend delivery webhook"
  say "The gateway receives Resend's email events at $GATEWAY_URL/api/v1/webhooks/resend (#143)."
  if secret_exists "$secret" && ! confirm "$secret exists. Open Resend to check the endpoint and its events anyway?"; then
    ok "kept the Resend endpoint and $secret as they are"
  else
    open_url "https://resend.com/webhooks"
    step "Select Add Webhook, or open the webhook that already uses this URL."
    step "Endpoint URL: $GATEWAY_URL/api/v1/webhooks/resend"
    step "Events (skip any that Resend does not list):"
    say "  $RESEND_EVENTS"
    step "Add the webhook, then open it. Its details page shows the signing secret: copy it."
    pause "Press Enter when the webhook is saved and the signing secret is copied"
    mode="replace"
  fi
  ensure_pasted_secret "$secret" "Paste the Resend signing secret (hidden):" "$mode"
  grant_secret_accessor "$secret" "$GATEWAY_SA"
  pause
}

stage_twilio_callbacks() {
  stage "Twilio status callbacks"
  say "The gateway checks the signature on Twilio's delivery callbacks with the account auth token."
  grant_secret_accessor apicenter-shared-twilio-auth-token-prod "$GATEWAY_SA"
  printf '\n'
  say "No Twilio console change is needed. sms.yaml sets TWILIO_STATUS_CALLBACK_URL to"
  say "$GATEWAY_URL/api/v1/webhooks/twilio, and the SMS runtime sends it as StatusCallback"
  say "with every message (packages/runtime/src/delivery.js)."
  pause
}

stage_paymongo_webhooks() {
  stage "PayMongo webhooks"
  say "Each payment runtime receives PayMongo events at $GATEWAY_URL/api/v1/shared/payment/webhooks/<env>."
  say "It handles ${PAYMONGO_EVENTS//,/, }. payment.paid also covers payment-link"
  say "payments, whose origin is \"links\"."
  note "Webhook API responses include each webhook's signing secret, so only IDs, URLs, statuses, and events are shown."
  note "This wizard never creates a webhook: a new one has a new signing secret for apicenter-payments-<env>-webhook-secret."
  paymongo_environment test
  paymongo_environment live
  pause
}

stage_github_secrets() {
  local names name question
  stage "GitHub smoke test secrets"
  say "The deployed quota smoke in api-center-ci.yml needs APICENTER_SMOKE_APPROVER_TOKEN (#141): a JWT for a"
  say "dedicated operator identity that holds the platform:admin scope. It must be a different identity from"
  say "the one behind APICENTER_SMOKE_TRIBE_TOKEN, because approvals reject the requester's own identity."
  say "API_CENTER_PLATFORM_ADMIN_SECRET is a separate credential, not an approver JWT."
  note "Details: docs/developer/tribe-api-quotas.md, CI Smoke Requirements."
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    later "set the GitHub secret APICENTER_SMOKE_APPROVER_TOKEN and check the other smoke secrets (gh is missing or signed out)"
    pause
    return 0
  fi
  names=$(gh secret list 2>/dev/null | cut -f1 || true)
  question="Set the GitHub secret APICENTER_SMOKE_APPROVER_TOKEN now?"
  if grep -qx APICENTER_SMOKE_APPROVER_TOKEN <<<"$names"; then
    question="APICENTER_SMOKE_APPROVER_TOKEN exists. Replace it?"
  fi
  if confirm "$question"; then
    WIZARD_SECRET_INPUT=""
    ask_secret WIZARD_SECRET_INPUT "Paste the approver JWT (hidden):"
    if [[ -n "$WIZARD_SECRET_INPUT" ]]; then
      set_secret APICENTER_SMOKE_APPROVER_TOKEN "$WIZARD_SECRET_INPUT"
    else
      later "set the GitHub secret APICENTER_SMOKE_APPROVER_TOKEN (nothing was entered)"
    fi
    WIZARD_SECRET_INPUT=""
  elif ! grep -qx APICENTER_SMOKE_APPROVER_TOKEN <<<"$names"; then
    later "set the GitHub secret APICENTER_SMOKE_APPROVER_TOKEN"
  fi
  printf '\n'
  names=$(gh secret list 2>/dev/null | cut -f1 || true)
  for name in APICENTER_SMOKE_BASE_URL APICENTER_SMOKE_TRIBE_TOKEN API_CENTER_PLATFORM_ADMIN_SECRET; do
    if grep -qx "$name" <<<"$names"; then
      ok "GitHub secret $name exists"
    else
      later "set the missing GitHub secret $name (gh secret set $name)"
    fi
  done
  pause
}

stage_google_sign_in() {
  stage "Google sign-in: consent screen and redirect URIs"
  say "gauth signs users in with the shared Google OAuth client in $PROJECT_ID (infra/gcp/GAUTH_OPERATIONS.md)."
  open_url "https://console.cloud.google.com/apis/credentials/consent?project=$PROJECT_ID"
  step "This opens Google Auth Platform. Go to Audience and check the user type:"
  say "  Internal lets only users in your Google Workspace organization sign in, and needs a project that"
  say "  belongs to an organization. External lets any Google account sign in."
  step "Check the publishing status. While it is Testing, only listed test users can sign in (at most 100),"
  say "  and each test user's authorization expires seven days after they consent. Before general sign-in,"
  say "  select Publish app to move it to In production. An External app that requests sensitive or"
  say "  restricted scopes may need Google's verification first."
  pause "Press Enter when the audience settings are right"
  open_url "https://console.cloud.google.com/apis/credentials?project=$PROJECT_ID"
  step "Open the OAuth client whose ID is stored in apicenter-shared-google-client-id-prod."
  step "Under Authorized redirect URIs, add every redirect URL a team saved on the management console's"
  say "  Google sign-in page. Scheme, host, path, and trailing slash must match exactly."
  note "A project that saved its own Google client ID on that page adds its URLs to its own client instead."
  pause "Press Enter when the redirect URIs are added"
}

stage_history_purge() {
  local image="$IMAGE_REPOSITORY/apicenter-history-purge:latest"
  local registry="${REGION}-docker.pkg.dev"
  stage "History purge job (optional)"
  say "The purge job deletes history rows older than their retention windows (#63)."
  note "Runbook: docs/operations/history-retention.md"
  if ! confirm "Set up the history purge job now?"; then
    later "set up the history purge job (stage 11)"
    return 0
  fi
  ensure_service_account apicenter-history-purge "APICenter history purge"
  printf '\n'
  step "Create the purge login role first, with the SQL under Running the purge in docs/operations/history-retention.md:"
  say "  create role apicenter_purge login password '...' in role api_center_retention;"
  ensure_pasted_secret apicenter-history-purge-database-url \
    "Paste the purge database URL, postgres://apicenter_purge:...@HOST/DB (hidden):"
  grant_secret_accessor apicenter-history-purge-database-url "$PURGE_SA"
  printf '\n'
  if ! command -v docker >/dev/null 2>&1 || ! docker info >/dev/null 2>&1; then
    later "build and push $image, deploy the job, and run its first dry run (docker is not available here)"
    pause
    return 0
  fi
  say "history-purge.yaml passes --dry-run, so the first execution only reports what it would delete."
  if ! confirm "Build and push $image, deploy the job, and run its first dry run?"; then
    later "build and push $image, deploy the job, and run its first dry run"
    pause
    return 0
  fi
  if ! grep -qs "$registry" "${DOCKER_CONFIG:-$HOME/.docker}/config.json" \
      && confirm "Docker has no credentials for $registry. Run gcloud auth configure-docker $registry?"; then
    gcloud auth configure-docker "$registry" --quiet || true
  fi
  if docker build -f docker/Dockerfile.history-purge -t "$image" . \
      && docker push "$image" \
      && gcloud run jobs replace infra/gcp/cloud-run/history-purge.yaml --region "$REGION" --project "$PROJECT_ID" \
      && gcloud run jobs execute apicenter-history-purge --region "$REGION" --project "$PROJECT_ID" --wait; then
    ok "the first dry run finished"
    say "Read its apicenter_history_purge log line. Remove --dry-run only when the counts look right"
    say "(step 4 of the runbook)."
  else
    later "finish building, deploying, or dry-running the history purge job (a command failed; see the error above)"
  fi
  pause
}

stage_database() {
  local -a supabase=(npx --yes supabase)
  local listing counts remote_only local_only typed=""
  stage "Database schema"
  say "#113 replaced the migration history with one baseline, supabase/migrations/20261011080000_baseline.sql."
  say "A database migrated with the old files still records versions that no longer exist here, and the"
  say "baseline cannot be pushed on top of them."
  if ! command -v npx >/dev/null 2>&1; then
    later "link the Supabase project and apply the baseline (npx is not installed)"
    pause
    return 0
  fi
  if ! npx --no-install supabase --version >/dev/null 2>&1 \
      && ! confirm "Download the Supabase CLI with npx (npm package supabase)?"; then
    later "link the Supabase project and apply the baseline"
    pause
    return 0
  fi
  if ! "${supabase[@]}" projects list >/dev/null 2>&1 \
      && confirm "The Supabase CLI is not signed in. Run npx supabase login? It opens a browser."; then
    "${supabase[@]}" login || true
  fi
  ask SUPABASE_PROJECT_REF "Supabase project ref (the <ref> in https://supabase.com/dashboard/project/<ref>):"
  if [[ -z "$SUPABASE_PROJECT_REF" ]]; then
    later "link the Supabase project and apply the baseline (no project ref was entered)"
    pause
    return 0
  fi
  write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
  if ! "${supabase[@]}" link --project-ref "$SUPABASE_PROJECT_REF"; then
    later "link the Supabase project $SUPABASE_PROJECT_REF (npx supabase link failed)"
    pause
    return 0
  fi
  if ! listing=$("${supabase[@]}" migration list --linked); then
    later "compare migrations with npx supabase migration list --linked (it failed)"
    pause
    return 0
  fi
  printf '%s\n' "$listing"
  # Rows with a REMOTE version and no LOCAL one exist only in the remote history; the reverse are not applied yet.
  counts=$(python3 -c '
import re, sys
remote_only = local_only = 0
for line in sys.stdin:
    cells = [cell.strip() for cell in re.split("[\u2502|]", line)]
    if len(cells) < 3:
        continue
    local, remote = cells[0], cells[1]
    if re.fullmatch(r"\d+", remote) and not local:
        remote_only += 1
    elif re.fullmatch(r"\d+", local) and not remote:
        local_only += 1
print(remote_only, local_only)
' <<<"$listing")
  read -r remote_only local_only <<<"$counts"
  if (( remote_only > 0 )); then
    warn "The remote database records $remote_only migration version(s) that are not in supabase/migrations."
    say "That is the old history, and it has to go. npx supabase db reset --linked drops everything in the"
    say "linked database and applies the baseline. It deletes all data in that database (there is none yet)."
    printf '  %sType RESET to reset the linked database, or press Enter to skip:%s ' "$BOLD" "$RESET"
    read -r typed || true
    if [[ "$typed" != "RESET" ]]; then
      later "reset the linked database with npx supabase db reset --linked so the baseline applies"
    elif ! "${supabase[@]}" db reset --linked; then
      later "reset the linked database with npx supabase db reset --linked (it failed)"
    fi
  elif (( local_only > 0 )); then
    say "The remote has no versions missing here. npx supabase db push applies $local_only migration(s)."
    if ! confirm "Run npx supabase db push?"; then
      later "apply the baseline with npx supabase db push"
    elif ! "${supabase[@]}" db push; then
      later "apply the baseline with npx supabase db push (it failed)"
    fi
  else
    ok "the linked database has every migration in supabase/migrations"
  fi
  pause
}

stage_deploy_order() {
  local build="gcloud builds submit --project=$PROJECT_ID --config=infra/gcp/cloud-build"
  local replace="gcloud run services replace infra/gcp/cloud-run"
  local flags="--project=$PROJECT_ID --region=$REGION"
  stage "Deploy order"
  say "This stage runs nothing. Build the images first, through the repo's Cloud Build configs. Run them"
  say "from the repository root; each config also deploys what it builds."
  printf '\n'
  say "$build/apicenter-shared-services-cloud-run.yaml ."
  note "    builds gauth, email, sms, otp, and geo, then replaces those services"
  say "$build/apicenter-payments-cloud-run.yaml ."
  note "    builds and deploys apicenter-payments-test"
  say "$build/apicenter-payments-cloud-run.yaml --substitutions=_SERVICE_NAME=apicenter-payments-live,_STABLE_IMAGE=$IMAGE_REPOSITORY/apicenter-payments:cloud-run-live,_MANIFEST=infra/gcp/cloud-run/apicenter-payments.live.yaml ."
  say "$build/api-center-cloud-run.yaml --substitutions=_SERVICE_NAME=api-center,_STABLE_IMAGE=$IMAGE_REPOSITORY/api-center:cloud-run-prod,_MANIFEST=infra/gcp/cloud-run/api-center.prod.yaml ."
  note "    without these substitutions the gateway config deploys api-center-staging"
  printf '\n'
  say "To redeploy from the manifests, keep this order. The gateway goes last: it reads the new secrets"
  say "and calls the services before it."
  step "1. gauth: $replace/gauth.yaml $flags"
  step "2. email: $replace/email.yaml $flags"
  step "3. sms: $replace/sms.yaml $flags"
  step "4. payments test: $replace/apicenter-payments.test.yaml $flags"
  step "5. payments live: $replace/apicenter-payments.live.yaml $flags"
  step "6. gateway: $replace/api-center.prod.yaml $flags"
  pause "Press Enter to finish"
}

